            let tracked ghost_data0 = NrLogAppendExecDataGhost {
                local_updates,
                ghost_replica,
                combiner,
                cb_combiner,
                request_ids,
            };
            ghost_data_new =
            self.execute(replica_token, responses, actual_replica, Tracked(ghost_data0));
