               |i: int| pre.tail - pre.buffer_size <= i < new_tail - pre.buffer_size
                 ==> stored_type_inv(#[trigger] withdrawn[i], i, pre.cell_ids[log_entry_idx(i, pre.buffer_size) as int], pre.unbounded_log_instance) by {

